mapper.select:
select template_id, event_type, entry_seq, direction, subject_code, subject_name,
       auxiliary_type, summary_template, status, create_by, create_time
from fin_voucher_template


        and event_type = #{eventType}


        and direction = #{direction}


        and subject_code like concat('%', #{subjectCode}, '%')


        and status = #{status}


order by event_type asc, entry_seq asc

select count(1)
from fin_voucher_template
where event_type = #{eventType}
  and entry_seq = #{entrySeq}

  and template_id != #{excludeId}

select count(1)
from fin_voucher_template
where subject_code = #{subjectCode}

mapper.update:
update fin_voucher_template
event_type = #{eventType}, entry_seq = #{entrySeq}, direction = #{direction}, subject_code = #{subjectCode}, subject_name = #{subjectName}, auxiliary_type = #{auxiliaryType}, summary_template = #{summaryTemplate}, status = #{status},
where template_id = #{templateId}

mapper.select:
select e.entry_id, e.voucher_event_id, e.voucher_no, e.entry_seq, e.direction, e.subject_code, e.subject_name, e.auxiliary_type, e.auxiliary_name, e.debit_amount, e.credit_amount, e.summary, e.create_time, coalesce(v.voucher_date, v.event_date) as voucher_date, v.bill_no from fin_voucher_entry e inner join fin_voucher_event v on v.voucher_event_id = e.voucher_event_id
and v.bill_type = #{billType}
and v.event_type = #{eventType}
and v.status = #{status}
and e.voucher_no like concat('%', #{voucherNo}, '%')
order by e.voucher_no asc, e.entry_seq asc, e.entry_id asc

select count(1)
from fin_voucher_entry
where subject_code = #{subjectCode}
